-- Recreate doctor website content tables from content-export-2026-06-07.json
-- Generated from exportDate: 2026-06-07T11:30:43.530Z
-- WARNING: This drops and recreates public.blog_posts, public.specialties, and public.videos.

begin;

drop table if exists public.videos cascade;
drop table if exists public.specialties cascade;
drop table if exists public.blog_posts cascade;

create table public.blog_posts (
  id bigint generated by default as identity primary key,
  slug text unique not null,
  title text not null,
  excerpt text,
  content text not null,
  image text,
  author text default 'Dr. Sabri Keser',
  category text,
  read_time text,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table public.specialties (
  id bigint generated by default as identity primary key,
  slug text unique not null,
  title text not null,
  description text,
  icon text,
  what_is text,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table public.videos (
  id bigint generated by default as identity primary key,
  title text not null,
  youtube_url text not null,
  youtube_id text not null,
  display_order integer default 0,
  is_active boolean default true,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

alter table public.blog_posts enable row level security;
alter table public.specialties enable row level security;
alter table public.videos enable row level security;

create policy "Public can read blog posts" on public.blog_posts for select to anon, authenticated using (true);
create policy "Authenticated users can insert blog posts" on public.blog_posts for insert to authenticated with check (true);
create policy "Authenticated users can update blog posts" on public.blog_posts for update to authenticated using (true) with check (true);
create policy "Authenticated users can delete blog posts" on public.blog_posts for delete to authenticated using (true);

create policy "Public can read specialties" on public.specialties for select to anon, authenticated using (true);
create policy "Authenticated users can insert specialties" on public.specialties for insert to authenticated with check (true);
create policy "Authenticated users can update specialties" on public.specialties for update to authenticated using (true) with check (true);
create policy "Authenticated users can delete specialties" on public.specialties for delete to authenticated using (true);

create policy "Public can read videos" on public.videos for select to anon, authenticated using (is_active = true);
create policy "Authenticated users can insert videos" on public.videos for insert to authenticated with check (true);
create policy "Authenticated users can update videos" on public.videos for update to authenticated using (true) with check (true);
create policy "Authenticated users can delete videos" on public.videos for delete to authenticated using (true);

insert into public.blog_posts (id, slug, title, excerpt, content, image, author, category, read_time, created_at, updated_at) values
  ('2', 'yillik-kontrollerin-onemi', 'Yıllık Kontrollerin Önemi', 'Düzenli sağlık taramalarının erken teşhis ve önleme için neden çok önemli olduğunu keşfedin.', '<p>Yıllık sağlık kontrolleri, hastalıkların erken teşhisinde hayati öneme sahiptir.</p><p>Kan testleri, tansiyon ölçümü, kolesterol kontrolü ve diğer tarama testleri sayesinde birçok hastalık erken dönemde yakalanabilir. Erken teşhis, tedavi başarısını önemli ölçüde artırır.</p>', '/doctor-medical-office.png', 'Dr. Sabri Keser', 'Koruyucu Hekimlik', '4 dakika', '2025-11-25T12:00:00.000Z', '2026-06-07T11:30:43.530Z'),
  ('3', 'kronik-hastaliklari-yonetmek', 'Kronik Hastalıkları Etkili Bir Şekilde Yönetmek', 'Doğru yönetim ve yaşam tarzı değişiklikleri ile kronik hastalıklarla iyi yaşamaya dair uzman tavsiyeleri.', '<p>Kronik hastalıklar doğru yönetim stratejileri ile kontrol altında tutulabilir.</p><p>İlaç tedavisine uyum, düzenli doktor takibi ve yaşam tarzı değişiklikleri başarılı yönetimin anahtarıdır. Diyabet, hipertansiyon gibi kronik hastalıklar ile kaliteli bir yaşam sürmek mümkündür.</p>', '/medical-consultation.png', 'Dr. Sabri Keser', 'Kronik Hastalık', '6 dakika', '2025-11-25T12:00:00.000Z', '2026-06-07T11:30:43.530Z');
select setval(pg_get_serial_sequence('public.blog_posts', 'id'), coalesce((select max(id) from public.blog_posts), 1), true);

insert into public.specialties (slug, title, description, icon, what_is, created_at, updated_at) values
  ('androloji', 'Androloji', 'Erkek sağlığı ve cinsel işlev', 'Stethoscope', '<h3>Androloji Nedir?</h3><p>Androloji, erkek üreme sistemi ve cinsel sağlık sorunlarının tanı ve tedavisi ile ilgilenen tıp dalıdır.</p><p>Erkek infertilitesi, hormonal dengesizlikler, cinsel işlev bozuklukları ve diğer erkek sağlığı sorunlarını kapsar. </p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('erkek-infertilitesi', 'Erkek İnfertilitesi', 'Kısırlık tanı ve tedavisi', 'Users', '<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                       ERKEK İNFERTİLİTESİ</strong></p><p class="ql-align-justify"><br></p><p class="ql-align-justify">Korunmasız 1 yıllık düzenli cinsel birliktelik sonucunda hamilelik olmama durumu infertilite olarak tanımlanmaktadır. Genel olarak çiftlerin %15’inde fertilite problemi saptanmaktadır. Bu sebeple başvuran çiftlerin %30-40’ında neden olarak erkek faktörü rol oynar. Erkek infertilitesine yol açan faktörler başlıca 4 başlık altında toplanır: </p><p>1. PRE TESTİKÜLER; Hipotalomo-hipofizer hastalıklar (sekonder hipogonadizm-hipogonadotropik hipogonadism-) (%1-2) </p><p>2. TESTİKÜLER hastalıklar (primer testiküler yetmezlik ve hipogonadizm-hipergonadotropik hipogonadism-) (%30-40) </p><p>3. POST TESTİKÜLER hastalıklar (tıkanıklık, cerrahiler vs) (%10-20) </p><p>4. Açıklanamayan İDİOPATİK infertilite (%25-50) </p><p class="ql-align-justify">WHO’nun son belirlediği semen analizi kriterlerine göre semen analizi anormal çıkan hastaları 2 ardışık semen analizi ile doğrulamak gerekir. Hiç sperm olmaması durumu olan azospermi varlığında ejakülat örneği 3000/dakika hızda 15 dakika boyunca santrifüj edilir ve sonrasında sperm varlığına bakılmalıdır.</p><p class="ql-align-justify">Açıklanamayan infertilite, embriyoların gelişiminde problem gözlenmesi, tekrarlayan düşük gibi durumlarda infertilite yaşayan erkeklerin değerlendirilmesinde sperm DNA fragmantasyon (SDF) testi yapılmalıdır. Deneysel olarak ejaküle spermde yüksek SDF bulunan hastalarda ICSI için testis sperminin kullanımı düşünülmelidir.</p><ul><li>&lt;%15: Düşük (iyi durumda) DNA hasarı</li><li>%15-30: Sınırda (kabul edilebilir) DNA hasarı</li><li>%30 üstü: Yüksek DNA hasarı</li></ul><p>&nbsp;Oligozospermi ve azoospermi vakalarında en azından serum total testosteron ve Folikül Stimüle Edici Hormon (FSH) / Luteinizan Hormon (LH) dahil olmak üzere hormonal değerlendirme yapılmalıdır.</p><p class="ql-align-justify">Azospermik erkeklerin büyük çoğunluğunda (2/3) obstrüktif olmayan azospermi saptanır. Bu olgularda karyotip anomalisi ve AZF delesyonları gibi Y kromozomunda oluşan genetik bozuklukların %15 civarında saptanması nedeniyle genetik testler yapılmalıdır. Azospermi ve oligozoospermisi (spermatozoa &lt;5 milyon/ml) olan tüm erkeklere tanı amaçlı standart karyotip analizi ve genetik danışmanlık önerilmelidir. Y-kromozom mikrodelesyon testi, sperm konsantrasyonu &lt;5 milyon sperm/ml olan erkeklerde önerilebilir, ancak sperm konsantrasyonu &lt;1 milyon sperm/ml olan erkeklerde zorunludur.</p><p>Klinefelter sendromlu erkekler için uzun süreli endokrin takibi ve uygun tıbbi tedavi gerekmektedir.</p><p class="ql-align-justify">Yq mikrodelesyonu olan erkekleri ve intrasitoplazmik sperm enjeksiyonu (ICSI) yapmak isteyen eşlerini, mikrodelesyonların OĞULLARA geçebileceği konusunda çiftlere bilgilendirme yapılmalıdır.</p><p class="ql-align-justify">Y kromozomu uzun kolu üzerinde bulunan AZF bölgesinde yer alan a, b ve c lokusları spermatogenezin normal olarak düzenlenmesini kontrol eder ve bu bölgelerde ortaya çıkan defektler değişik derecede sperm yapımında bozukluğa neden olurlar. AZFa bölgesini içeren Y kromozom delesyonlarında histopatolojik olarak “Sertoli cell only” sendromu bulunurken, AZFb ve AZFc bölgesindeki bozukluklarda erken ve geç maturasyon arresti görülmektedir. Testisten sperm elde etme oranı özellikle AZFc delesyonlarında %50’ye kadar çıkabilmektedir. Ancak AZF komplet delesyonu saptananlarda bugüne kadar sperme rastlanmamıştır. AZFa ve AZFb bölgelerini de içeren tam delesyonları olan hastalarda testiküler sperm ekstraksiyonu denenmemelidir. AZFc de denenebilir. Obstrüktif olmayan azoospermi, Sertoli hücre-sadece sendromu, erken veya geç olgunlaşma durması veya hipospermatogenezden kaynaklanabilir.&nbsp;Sertoli hücre-sadece sendromu bunların en yaygın olanıdır ve hemen ardından olgunlaşma durması gelir.</p><p class="ql-align-justify">Sertoli hücreleri, erkeklerde birçok hayati üreme işlevine sahiptir. Sperm hücrelerinin büyümesi ve beslenmesi için gerekli maddeleri salgılayarak spermatogonyumların düzgün büyümesi ve gelişmesinde önemli bir rol oynarlar. Sertoli hücreleri ayrıca, erkek fetüste Müllerian kanallarının gerilemesine yol açan anti-Müllerian hormonunu da salgılar.&nbsp;Anti-Müllerian hormon, erkek fetüste embriyogenezin erken aşamalarında herhangi bir iç dişi üreme organının gelişimini engeller.&nbsp;</p><p class="ql-align-justify">Sertoli hücreleri ayrıca hipotalamusta folikül uyarıcı hormon salgılanmasının aşağı düzenleyici etkisini sağlayan inhibin-B''yi de salgılar.&nbsp;</p><p class="ql-align-justify">Aktivin, Sertoli hücreleri tarafından salgılanan bir diğer üründür. Hipotalamusta spermatogenez için pozitif geri bildirim sağlar ve daha yüksek FSH seviyelerine yol açar.&nbsp;</p><p class="ql-align-justify">Vas deferens yapısal anormallikleri olan erkekleri (renal agenezi olmadan tek taraflı veya iki taraflı yokluk) ve partnerini kistik fibroz transmembran iletkenlik düzenleyici gen mutasyonları için test etmek gerekir.</p><p class="ql-align-justify">Klinik veya genetik incelemede genetik anormalliği bulunan tüm çiftlere ve kalıtsal bir hastalık taşıma potansiyeli olan hastalara genetik danışmanlık sağlanmalıdır.</p><p>Sonuç olarak; </p><p> Obstrüktif olmayan azospermide sperm testisten elde edilmelidir. </p><p> Diğer yöntemlerle karşılaştırıldığında, bu olgularda mikro-TESE ile sperm bulma oranları daha yüksektir. </p><p> Obstrüktif olmayan azospermide testis hacmi, FSH ve inhibin B düzeyleri ile sperm bulma oranları arasında ilişki yoktur. Sperm elde etmede tek prediktif faktör testis histopatolojisidir. </p><p> Klinefelter sendromlu hastalarda yaş ve preoperatif testosteron düzeyi prediktiftir. </p><p> Komplet AZFa ve AZFb delesyonu bulunduğunda testisten sperm elde edilememektedir. AZFc delesyonu olan azospermik grupta ise TESE ile sperm bulunabilmektedir (%75). </p><p> Parsiyel AZF a ve Parsiyel AZF b delesyonlarında TESE ile sperm elde edilebilir. Parsiyel AZF c delesyonlarında ejakulattan sperm eldesi (+), ejakulatta olmayanlarda TESE ile sperm elde edilebilir.&nbsp;</p><p><br></p><p><strong>TEDAVİ</strong>; <span style="color: rgb(2, 8, 23);">İnfertil erkeklerden üreme geçmişi, aile hikayesi, hayat tarzı ve alışkanlıkları hakkında bilgi alınmalıdır. Fizik muayene ve semen analizi yapılmalıdır. Obezitenin, düşük fiziksel aktivitenin, sigara içmenin ve yüksek alkol alımının sperm kalitesi ve testosteron seviyeleri üzerindeki zararlı etkileri hakkında hastaya bilgi verilmelidir. Sonuç olarak, infertil erkeklere doğurganlık şanslarını artırmak için yaşam tarzı faktörlerini iyileştirmelerini beslenme alışkanlıklarını değiştirmelerini önermeliyiz.</span> Öncelikle sebebe yönelik tedaviler planlanmalıdır, varikosel varsa cerrahi düşünülmelidir. Farklı kombinasyonlarla hastanın durumuna göre hormonal tedaviler planlanabilir. Antioksidan tedaviler önerilebilir. Bu tedavilerin tümü hasta ile birlikte ve kişiye özel olarak planlanmalıdır.</p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('erektil-disfonksiyon', 'Erektil Disfonksiyon', 'Sertleşme sorunu için çözümler', 'Activity', '<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;EREKTİL DİSFONKSİYON</strong></p><p><strong>Tanım</strong>; Erektil disfonksiyon (ED), tatmin edici cinsel performans için ereksiyona ulaşmada ve sürdürmede KALICI (bazı yayınlarda en az 6 ay devam etmesi gerekir denilmektedir) yetersizlik olarak tanımlanır. Son zamanlarda bir semptom olarak tanımlanmaktadır. 40 yaş altı erkeklerde %20 lere kadar, 40 yaş üstü erkeklerde ise yaşla artan bir şekilde yaklaşık %50 ler civarında bu problem ile karşılaşılmaktadır. Organik (%90) ve psikolojik sebepleri vardır. Organik sebepler arasında; vasküler (%70), sinirsel (%5), hormonal (%5) ve ilaçlar (%10) sayılabilir. Psikolojik olarak; depresyon, performans anksiyetesi, kültürel mitler, davranış bozuklukları (neyi ED olarak tanımlıyor? İkinci ilişki?) sayılabilir.</p><p><strong>Ereksiyon Fizyolojisi:</strong></p><p>Sertleşme temel olarak&nbsp;penis afferentlerinin harekete geçirilmesiyle, ayrıca görsel, koku ve hayali uyaranlarla başlatılabilen bir&nbsp;<a href="https://www.sciencedirect.com/topics/neuroscience/spinal-reflex" rel="noopener noreferrer" target="_blank">omurilik refleksidir. Refleks hem otonomik hem de&nbsp;</a><a href="https://www.sciencedirect.com/topics/neuroscience/somatics" rel="noopener noreferrer" target="_blank">somatik&nbsp;</a>efferentleri içerir ve supraspinal etkilerle modüle edilir. Sertleşme kontrolünde rol oynayan birkaç merkezi iletici tanımlanmıştır. DOPAMİN,&nbsp;<a href="https://www.sciencedirect.com/topics/neuroscience/acetylcholine" rel="noopener noreferrer" target="_blank">asetilkolin</a>, NİTRİK OKSİT(NO), oksitosin ve adrenokortikotropik/α-melanosit uyarıcı hormon gibi peptitler kolaylaştırıcı bir role sahip gibi görünmektedir, oysa SEROTONİN kolaylaştırıcı veya inhibe edici olabilir ve enkefalinler inhibe edicidir.</p><p>NO, penis damarlarının ve korpus kavernozumun gevşemesinde en önemli faktör olarak kabul edilir. Sinirlerden veya endotelden salınan diğer mediyatörlerin rolü kesin olarak belirlenememiştir.<a href="https://www.sciencedirect.com/topics/pharmacology-toxicology-and-pharmaceutical-science/erectile-dysfunction" rel="noopener noreferrer" target="_blank">&nbsp;Erektil disfonksiyon</a>&nbsp;(ED), penis düz kaslarının gevşeyememesinden kaynaklanabilir. Kısacası ereksiyonun mekanizması oldukça kompleks ve halen gizemi tam olarak çözülememiştir. Sempatik sistem genel anlamda vazokonstrüksiyon, kalp hızı artışı, terleme yaparken parasempatik sistem ile vazodilatasyon ve sakinleştirme görevi yapar.</p><p>Çoğu ilaç, penis dokusu üzerinde doğrudan etki göstererek penis düz kas gevşemesini kolaylaştırır; bunlara prostaglandin E1, NO donörleri, fosfodiesteraz inhibitörleri ve α-adrenoseptör antagonistleri dahildir.&nbsp;Ereksiyonun&nbsp;<a href="https://www.sciencedirect.com/topics/pharmacology-toxicology-and-pharmaceutical-science/nitric-oxide-donor" rel="noopener noreferrer" target="_blank">başlatılmasına&nbsp;</a>katılan&nbsp;<a href="https://www.sciencedirect.com/topics/neuroscience/phosphodiesterase-inhibitor" rel="noopener noreferrer" target="_blank">merkezi&nbsp;</a>sinir sistemindeki&nbsp;<a href="https://www.sciencedirect.com/topics/pharmacology-toxicology-and-pharmaceutical-science/dopamine-receptor" rel="noopener noreferrer" target="_blank">dopamin reseptörleri</a>&nbsp;ED tedavisinde hedef alınmıştır.<a href="https://www.sciencedirect.com/topics/neuroscience/apomorphine" rel="noopener noreferrer" target="_blank">&nbsp;Dil altı olarak uygulanan apomorfin</a>&nbsp;bu tür ilaçların ilkidir.</p><p><strong>Tanıda</strong> Erektil disfonksiyon (ED) ile başvuran her hastadan kapsamlı bir tıbbi (geçirilmiş prostat ve pelvik cerrahiler, pelvik travmalar, HT, kalp hastalıkları, diyabet, psikiyatrik hastalıklar ve ilaç kullanımları) ve cinsel öykü alınmalı. Sigara, alkol, obezite, yaşam stres faktörleri, kültürel yönler ve hastanın cinsel performansına ilişkin bilişsel faktörler dahil olmak üzere hedeflenmiş bir psikoseksüel öykü alınmalı. ED ile ilgili onaylanmış bir anket kullanılmalıdır (IIEF). </p><p>Dikkatli bir FM den sonra değiştirilebilen risk faktörlerini ve yaşam tarzı faktörlerini belirlemek ve tedavi etmek için glikoz-lipit profili, FSH, LH, Prolaktin ve total testosteron dahil olmak üzere laboratuvar testlerini değerlendirmemiz gerekir.</p><p><strong>Tedaviye</strong> ilk olarak yaşam tarzı değişikliğiyle başlanmalı daha sonra öncelikle sebebe (hormon yetmezliği, ilaç kullanımları, DM, hiperlipidemi, hipogonadism vs) bakılmalı. Daha sonra eşinde katılımıyla tıbbi tedaviyle birlikte davranış terapileri denenmelidir. İlk basamak ilaç tedavisi olarak PDE5 inhibitörleri kullanım şekli anlatılarak düşünülmelidir. İlacın kontrendike olduğu veya etki etmediği hastalarda alprostadil enjeksiyonları veya üretral formları kullanılmalı. Hafif ve orta ED vakalarında oral ilaçla birlikte ESWT tedavisine başlanmalıdır. ESWT, oral tedaviye yanıt yetersizliği olanlarda da ilk basamak tedavi olarak kullanılabilir. Bununla beraber vakum cihazları önerilebilir. Tüm bunlara yanıtsızlık durumlarında penil protez önerilmelidir.</p><h3><br></h3>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('prematur-ejekulasyon', 'Prematür Ejekülasyon', 'Erken boşalma yönetimi', 'Activity', '<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PREMATÜRE EJEKULASYON</strong></p><p><strong>Tanım</strong>; En az 3 bazı yayınlarda 6 ay aynı partnerle düzenli bir cinsel ilişkide her seferinde penetrasyon öncesi veya sırasında (1 dakika, 2 dakika, 7,25 dakikadan önce gibi farklı süreler olmakla birlikte) normal orgazm döngüsüne sahip bir kadının orgazmından önce aynı zamanda stres ve kaygı oluşturan boşalma durumudur. Prematür ejakülasyon (PE) erkek cinsel fonksiyon bozuklukları arasında ilk sırada yer almaktadır. Cinsel aktif dönemde ki erkeklerin en az %50-75’ inde görülür.</p><p>Avrupa üroloji guideline ise ilk cinsel ilişkiden itibaren hemen tamamen penetrasyondan önce veya sonrasındaki yaklaşık bir dakika içerisinde meydana gelen ejakülasyon (<strong>yaşam boyu PE veya Primer PE</strong>) veya IELT (intravajinal ejekulatuvar latency time, ejekulasyon süresi)’ de 3 dakika ya da daha altı olacak şekilde, son zamanlarda başlayan hissedilir derecede azalma (<strong>edinsel PE veya Sekonder PE</strong>) diye adlandırılabilir.</p><p>• Tüm veya neredeyse tüm vajinal penetrasyonlarda ejakülasyonu geciktirememe </p><p>• Kaygı, rahatsızlık, hayal kırıklığı ve/veya cinsel yakınlıktan kaçınma gibi kişide olumsuz sonuçlar doğurur. </p><p>Diğer PE benzeri cinsel kaygılar, erken boşalma ile karışabilen ve herhangi bir cinsel işlev <strong>bozukluğunun olmadığı</strong> durumlardır. <strong>Doğal değişken PE</strong> ve <strong>subjektif PE</strong> olarak 2 tipi vardır. Doğal değişken PE, kişinin farklı zaman/partner ile yaşayabileceği bir durumdur. Bu alt tür PE, normal cinsel deneyimin bir çeşidi olarak kabul edilir. Subjektif PE’ de kişilerin ejakülasyon süresi aslında 5 dakika ve üzerindedir. Fakat bu kişilerde sürenin daha kısa olduğu ve kontrol eksikliği algısı vardır. </p><p><strong>Tanı</strong>; Yaşam boyu veya primer olanda özellikle hastanın hikayesi ve fizik muayene önemlidir. Çok fazla tetkik ihtiyacı yoktur. Ancak Edinsel PE’ de ED, hipo/hipertiroidi, prostatitler araştırılmalıdır. Laboratuvar olarak tit, idrar kültürü, tiroid fonksiyon testleri, prolaktin, testosteron (bazı çalışmalarda prolaktin düşüklüğü ve testosteron yüksekliği görülmüş ancak tam ilişki kurulamamış) bakılmalıdır.</p><p><strong>Tedavi ve Takipte</strong> PEP anketi ve Klinik Global izlenim değişim anketi kullanılabilir.</p><p>Tedavide anlık yani ilişki öncesi hapları ve krem/spreyler ile sürekli kullanılan haplar bulunmaktadır. Medikal olarak onaylanmış tek ürün Dapoksetin 30 ve 60 mg SSRI (serotonin ejekulasyon sırasında hücre dışına salınır, bir müddet sonra tekrar hücre içine girer. Bu grup ilaçlar hücre içine geri alımı engelleyerek ejekulasyon süresini uzatırlar) sınıfı antidepresandır. İlişkiden 1-3 saat önce 30 mg ile başlanır. İlaç etkinliği için 4 haftada en az 6 kez kullanım/cinsel ilişki olmalıdır. Normalde 24 saatte bir tane kullanılabilir. Yan etkileri çok nadirdir. Boşalma süresi yaklaşık 4 kat artar. Ciddi bir yan etki olmamışsa ve gerekli sonuç alınamamışsa 60 mg kullanılabilir. Diğer SSRI lar gibi cinsel istekte azalma ve ed bildirilmemiştir. Medikal tedavi dışında davranış terapileri çok etkili ve ilk aşamada düşünülmelidir. Terapide sıkma tekniği ve dur başla tekniği çalışılmalıdır. Terapinin en önemli handikapı eş yardımı ve terapi seans sayı ve süre uzunluğudur bu durumda uyumu azaltmaktadır.</p><p>Sık ve düzenli bir ilişki olmalı, </p><p>İlişki yavaş ve sabit ritimle olmalı, </p><p>Perineal bölgedeki pubokoksigeal kaslar 8 şeklindedir ve anüs ile penis kök bölgesinde bulunur, bunlara aşk kasları da denilmektedir. Bu kaslar hem idrar kontinansı hem de ejekulasyon kontrolünde önemlidir. <strong>İdrarımızı tutmak için bu kasları kasmamız gerekirken ejekulasyonu ertelemek/tutmak için bu kasları gevşek tutmamız gerekmektedir. Bu nedenle ejekulasyon kontrolünde ters kegel egzersizleri önerilmektedir. </strong>İlişki sırasında düzenli olarak burundan nefes alıp ağızdan vererek bu kasların gevşemesi sağlanmalıdır. Gaz çıkarıyormuş gibi yaparak bu kaslar gevşek tutulabilir. Gün içinde en az 5 er saniyelerle ters kegel denen bu eksersizler yapılmalıdır. </p><p>Sexüel döngüdeki istek/uyarılma, plato, orgazm ve gevşeme basamaklarındaki plato döneminde sarı ışık diyebileceğimiz an kırmızı olmadan yani plato bölgesindeyken mutlaka yavaşlama veya durma gerekir. En az bir dakika beklenmeli bu arada eş yardımıyla sevişme veya nefes eksersizleri yapılmalı. </p><p>Bel gevşekliği tanımı gereği, bel kaslarını güçlendirici eksersizler yapılmalıdır.</p><p>Boşalma süresini uzatabilmek için farklı ilişki pozisyonları hekim görüşüyle değerlendirilmedir.</p><h3><br></h3>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('peyronie-penis-egriligi', 'Peyronie (Penis Eğriliği)', 'Değerlendirme ve tedavi', 'Droplets', '<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PEYRONİE DİSEASE (PD)</strong></p><p><strong>Penis Eğriliği (Peyronie) Nedir?</strong></p><p>Ereksiyon (penis sertleşmesi) sırasında penisin düz olması gerekirken penis dokusunda plak oluşumu sonucu penisin eğrilmesi durumudur. Ağrı, peniste küçülme ve cinsel fonksiyon bozukluğuna neden olabilir. Bu durum doğuştan olabileceği gibi daha sonra da oluşabilir. penis eğriliği teşhisi Üroloji doktoru tarafından konulmalıdır.</p><p><br></p><p><strong>Penis Eğriliğinin Nedenleri</strong></p><p>Görülme sıklığı daha çok 40 yaş üstünde artar. Nedeni henüz kesin olarak ortaya konmamıştır. Sebep olarak en sık penis üzerindeki küçük kan damarlarının hasar görmesi olduğu kabul edilir. Şiddetli cinsel birliktelik, travma, ağır spor faaliyetleri gibi durumlar bu kan damarlarının hasar görmesine neden olabilir.</p><p><br></p><p>40 yaş üzeri, diyabete bağlı erektil disfonksiyona sahip, p<a href="https://www.acibadem.com.tr/ilgi-alani/prostat-kanseri/" rel="noopener noreferrer" target="_blank">r</a>ostat&nbsp;ameliyatı geçirmiş, o<a href="https://www.acibadem.com.tr/ilgi-alani/otoimmun-hastaliklar/" rel="noopener noreferrer" target="_blank">t</a>oimmün&nbsp;bozukluğu olan ve ailesinde peyronie hastalığı öyküsü bulunan kişilerde görülme olasılığı daha yüksektir.</p><p><br></p><p>Doğuştan penis eğriliği konjenital penil kruvatür ya da kordi olarak tanımlanır. Bu durum peyronie hastalığından farklı bir durumdur. Doğuştan penis eğriliği genellikle ergenlik dönemine kadar fark edilmez. Çoğunlukla ilk ereksiyon sırasında fark edilen bu durumu çocuğun ailesiyle paylaşması, teşhisin konması ve tedavinin başlatılması açısından önemlidir. Aşırı eğrilik olan durumlardaysa ereksiyona gerek olmadan da fark edilebilir. Doğuştan penis eğriliği, idrar deliğinin doğru konumunda olmaması ve inmemiş testis gibi diğer doğumsal ürolojik anomalilerle birlikte de görülebilir.</p><p><br></p><p><strong>Penis eğriliğinin Belirtileri Nelerdir?</strong></p><ul><li>Peniste özellikle ereksiyon sırasında belli olan ciddi eğrilik,</li><li>Cinsel ilişki ya da ereksiyon sırasında ağrı,</li><li>Ereksiyonun sürdürülmesinde zorlanma,</li><li>Cinsel birliktelik sırasında partnerin ağrı hissetmesi,</li><li>Penis gövdesinde mercimek büyüklüğünde sert dokular,</li><li>Penis boyunda küçülme,</li><li>Cinsel ilişkiye girmede zorlanma,</li><li>Anormal kıvrımlı penis görünümü.</li></ul><p><strong>Penis Eğriliği Tedavisi</strong></p><p>Penis eğriliğinin derecesine, hastalığa neden olan faktörlere ve hastanın şikâyetlerine göre&nbsp;penis eğriliğinin tedavisi mümkündür.</p><p>Penis eğriliğinin ilişkiye engel olmaması ve ağrı yoksa Ürolog tarafından hasta takip edilebilir. </p><p><strong>Konservatif tedavi;</strong> Penis eğriliğinin konservatif tedavisi, öncelikle, hastalığın erken evresindeki hastalarda ağrıyı gidermek ve hastalığın ilerlemesini önlemek için ek bir tedavi olarak veya, aktif faz sırasında hasta diğer tedavi seçeneklerini reddeder ise verilir. Oral farmakoterapi, intralezyonel enjeksiyon tedavisi, şok dalgası tedavisi <strong>(ESWT)</strong> ve diğer topikal tedaviler dahil olmak üzere çeşitli seçenekler mevcuttur. Ameliyatın uygun olmadığı veya hasta tarafından kabul edilmediği durumlarda konservatif tedavi önerilebilir.</p><p>Penis eğriliğinin akut fazında penil ağrıyı tedavi etmek için ekstrakorporeal şok dalgası tedavisi (<strong>ESWT</strong>) kullanılabilir. ESWT ağrı ve ereksiyon probleminde faydalıdır ancak eğriliği düzeltmez.</p><p>Fosfodiesteraz tip 5 inhibitörleri, Fosfodiesteraz tip 5 inhibitörleri ilk olarak 2003 yılında kollajen birikimini azaltması ve transforming growth factor (TGF)-b1’in&nbsp;inhibisyonu yoluyla apoptozu arttırması nedeniyle PD tedavisinde önerilmiştir. Eşlik eden erektil disfonksiyonu tedavi etmek için veya deformite penetrasyonda zorluğa neden oluyor ise penetrasyonu optimize etmek için de kullanılabilir.</p><p>Dorsal veya lateral &gt; 30º stabil eğriliği olan ve minimal invaziv bir prosedür arzulayan hastalarda <strong>interferon alfa-2b i</strong>le intralezyonel tedavi önerilebilir. (12 hafta süresince 2 haftada bir 10 mL salin içinde 5x10.6 ünite IFNα-2b’nin toplam altı enjeksiyonu), plaseboya kıyasla penis eğriliğini, plak boyutu ile yoğun- luğunu ve ağrıyı önemli ölçüde iyileştirmiştir. Ayrıca, penil kan akımı ile ilgili parametrelerde de iyileşmeler görülmüştür [953, 964, 965]. Plak lokalizasyonundan bağımsız olarak, IFNα-2b etkili bir tedavi seçeneğidir. IFNα-2b ile tedavi, plak lokalizasyonundan bağımsız olarak PD’li çoğu erkekte eğrilikte &gt; %20’lik bir azalma sağlar [966]. IFNα-2b enjeksiyonundan önce NSAID’ler ile etkili bir şekilde tedavi edilebilen sinüzit ve grip benzeri semptomları içeren hafif yan etkilerin olması ve mevcut verilerin orta düzeydeki kanıt seviyesi göz önüne alındığında, şu an için, IFNα-2b stabil faz PD hastalarının tedavisinde önerilmektedir.</p><p>Cerrahi dışı tedavi talep eden stabil ve dorsal veya lateral eğriliği &gt;30º olan hastalara, plasebo etkileri yüksek olmasına rağmen, <strong>kollajenaz clostridium histolyticum (CCH)</strong> ile intralezyonel tedavi önerilebilir. 1985’ten beri kullanılmaktadır. 2014 yılında EMA, palpabl dorsal plağı, 30- 90° eğriliği ve ventral bölge dışında plağı bulunan stabil faz PD’li erkeklerin cerrahi dışı tedavisi için CCH’nin kullanımını onaylamıştır. Tüm çalışmalardaki orijinal tedavi protokolü, 4 siklusa kadar, her 6 haftada bir, 24-72 saat arayla 0,58 mg CCH’nin iki defa enjeksiyonundan oluşur. Evde penis germe, modelleme ve Vakum cihazlarıyla yapılan multimodal yaklaşımın yerini 4 haftalık aralıklarla, maksimum eğrilik noktası etrafındaki üç hat boyunca verilen ve siklus başına bir (0.9 mg, bir şişe) enjeksiyon uygulanmasından oluşan değiştirilmiş bir kısa protokol önerilmiştir. Böylece daha uzun PD süresi, daha büyük bazal penil eğrilik ve bazal plak yerleşimi olan hastaların tedavi şansının daha yüksek olduğu ortaya konmuştur. </p><p>CCH ile tedavi edilen çoğu PD hastasında penise lokalize en az bir hafif veya orta derecede yan etki [penil hematom (%50,2), penis ağrısı (%33,5), peniste şişme (%28,9) ve enjeksiyon bölgesinde ağrı (%24.1)] görülmüştür. Bunlar enjeksiyondan sonraki 14 gün içinde kendiliğinden düzelmiştir [958]. Bu yan etki profili, uygulanan enjeksiyon sayısından bağımsız olarak her enjeksiyondan sonra benzer bulunmuştur. Tedaviyle ortaya çıkan ciddi yan etkiler (TEAE’s) (%0,9) cerrahi tedavi gerektiren penil hematom ve korporeal yırtılmadır. IMPRESS verilerine ve kısaltılmış protokole göre, ciddi TEAE’leri önlemek için enjeksiyondan sonraki 4 hafta içinde cinsel ilişkiden kaçınılmalıdır. Son veriler, hastalığın akut fazında CCH tedavisinin etkili ve güvenli olabileceğini düşündürmektedir. Şiddetli eğriliği olan hastaların da penil kurvatürdeki azalma olması ihtimali nedeniyle, CCH enjeksiyonlarından yararlanabileceği öne sürülmüştür. Eğrilikteki azalma sonucu plak insizyonu ve greftleme yerine penil plikasyon yapılabilir ve bu şekilde, ereksiyon üzerinde daha olumsuz bir işlemden de kaçınılmış olur. </p><p><strong>İntralezyoner hyalüronik asit</strong>; akut faz PD’de intralezyonel hyaluronik asit enjeksiyonu intralezyonel verapamil ile karşılaştırılmış ve ağrı, eğrilik ile IIEF-15’te anlamlı iyileşme olduğu gözlenmiştir</p><p><strong>Cerrahi Tedavi</strong>; Hastalar 3-6 ay boyunca (veya PD başlangıcından sonra 9-12 aydan fazla süre geçmiş) stabil bir hastalığa sahip olmalıdır. Bunlara ek olarak, başarısız konservatif veya tıbbi tedaviler, yaygın penil plaklar veya hastalık stabil iken hastanın tercihi gibi diğer durumlarda da cerrahi düşünülebilir. Erektil Disfonksiyon varlığı çok önemlidir. Çünkü bu hastalarda yapılacak cerrahi işlem ereksiyonu daha da bozabilir. Bu hastalarda protez planlanabilir.</p><p><br></p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('penil-protez-genital-estetik', 'Penil Protez & Genital Estetik', 'Mutluluk çubuğu ve estetik cerrahiler', 'Slice', '<h3>Penil Protez ve Genital Estetik Nedir?</h3><p>İlaç tedavisine yanıt vermeyen erektil disfonksiyon için protez implantasyonu.</p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('eswt-sok-dalga', 'ESWT Şok Dalga', 'İlaçsız fonksiyon destek tedavisi', 'Waves', '<p>&nbsp;</p><p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ürolojide şok dalga tedavisi (ESWT)</strong></p><p><img src="//:0"></p><p class="ql-align-justify">ESWT (Extracorporeal Shock Wave Therapy)&nbsp;yani şok dalga tedavisi bazı ürolojik problemlerde yaklaşık 10 yıldır önemli bir tedavi seçeneği olarak ön plana çıkmış bulunmaktadır. Geçmiş dönemlerde böbrek taşlarının kırılmasında kullanılan bu teknoloji günümüzde ise daha düşük dozda kas-iskelet sisteminin kronik ağrılı durumlarının ve erektil disfonksiyon olarak tanımlanan peniste sertleşme bozukluklarının tedavisinde kullanılmaktadır. </p><p class="ql-align-justify"><strong>İçindekiler</strong></p><ul><li class="ql-align-justify"><a href="https://www.memorial.com.tr/saglik-rehberi/urolojide-sok-dalga-tedavisi-eswt#urolojide-sok-dalga-tedavisi-eswt-nedir" rel="noopener noreferrer" target="_blank">Ürolojide Şok Dalga Tedavisi (ESWT) Nedir?</a></li><li><a href="https://www.memorial.com.tr/saglik-rehberi/urolojide-sok-dalga-tedavisi-eswt#urolojide-sok-dalga-tedavisi-eswt-nasil-uygulanir" rel="noopener noreferrer" target="_blank">Ürolojide Şok Dalga Tedavisi (ESWT) Nasıl Uygulanır?</a></li><li><a href="https://www.memorial.com.tr/saglik-rehberi/urolojide-sok-dalga-tedavisi-eswt#urolojide-sok-dalga-tedavisi-eswt-avantajlari-nelerdir" rel="noopener noreferrer" target="_blank">Ürolojide Şok Dalga Tedavisi (ESWT) Avantajları Nelerdir?</a></li><li><a href="https://www.memorial.com.tr/saglik-rehberi/urolojide-sok-dalga-tedavisi-eswt#urolojide-sok-dalga-tedavisinin-eswt-fark-yaratan-ozellikleri-nelerdir" rel="noopener noreferrer" target="_blank">Ürolojide Şok Dalga Tedavisinin (ESWT) Fark Yaratan Özellikleri Nelerdir?</a></li><li><a href="https://www.memorial.com.tr/saglik-rehberi/urolojide-sok-dalga-tedavisi-eswt#urolojide-sok-dalga-tedavisinin-eswt-uygulama-alanlari-nelerdir" rel="noopener noreferrer" target="_blank">Ürolojide Şok Dalga Tedavisinin (ESWT) Uygulama Alanları Nelerdir?</a></li><li><a href="https://www.memorial.com.tr/saglik-rehberi/urolojide-sok-dalga-tedavisi-eswt#urolojide-sok-dalga-tedavisi-eswt-hakkinda-sik-sorulan-sorular" rel="noopener noreferrer" target="_blank">Ürolojide Şok Dalga Tedavisi&nbsp;(ESWT) hakkında sık sorulan sorular</a></li></ul><p><strong>&nbsp;</strong></p><p><strong>Ürolojide Şok Dalga Tedavisi (ESWT) Nedir?</strong></p><p class="ql-align-justify">Ürolojide şok dalga tedavisi ESWT (Extracorporeal Shock Wave Therapy) vücudun dışında oluşturulan yüksek frekanslı ve basınçlı ses dalgalarının, bir aplikatör vasıtasıyla hastalıklı bölgeye uygulanmasıdır. </p><p><strong>Ürolojide Şok Dalga Tedavisi (ESWT) Nasıl Uygulanır?</strong></p><p>Bir jel yardımı ile penis üzerinde belirlenmiş ortalama 5 farklı noktaya şok dalgaları gönderilir. Uygulama esnasında ağrı olmaz, sadece karıncalanma hissedilebilir. Bir seans yaklaşık 20 dakika sürer ve toplamda 6 ila 24 seans uygulama yapılır. Her bir seans arası uygulama yeri ve hekim görüşüne göre1-7 gündür.</p><p><strong>Ürolojide Şok Dalga Tedavisi (ESWT) Avantajları Nelerdir?</strong></p><ul><li>ESWT ağrısızdır, anestezi ve hastaneye yatış gerektirmez. Bu yöntemle hızlıca sonuç alınır.</li><li>ESWT tedavisinin ardından ciltte oluşan hafif kızarıklık ve şişlik dışında önemli bir yan etkisi beklenmez. Hastalar tedavi seanslarından sonra günlük işlerine devam edebilir.</li><li>Seçilmiş vakalarda yüzde 80-90 oranında kalıcı iyileşme sağlanabilir.</li><li>Bazı hastalarda ilk seanstan itibaren 1 haftalık süre içerisinde iyileşmeler görülebilir. Ancak iyileşme süreci genel olarak ilk seanstan ortalama 1 ay sonra başlar. Kalıcı iyileşme için ise yaklaşık 8-12 haftalık bir süre beklenir.</li><li>ED tedavisinde haftada 2 kez en az 6 seans duruma göre 12 seans olarak uygulanır.</li><li>Penis uzatmalarda PRP ile birlikte ayda 1 kez en az altı ay uygulama yapılır.</li><li>Prostatit tedavisinde haftada 1 seans (20 dakika) olmak üzere toplam 4-6 seanslık uygulama ile kısa sürede etkili tedavi imkanı sağlar. </li><li>Uygulama öncesi ve sonrasında herhangi bir özel hazırlık gerekmez. Uygulaması basit ve hastaya herhangi bir rahatsızlık, ağrı vermez. Anestezi veya ağrı kesici kullanmaya ihtiyaç duyulmamaktadır.</li><li>Seans sonrası hiçbir aktivite kısıtlaması olmadan, hemen günlük yaşantıya devam edilebilir. Prostatın tüm bölgelerine ulaşarak etkili uygulama yapılabilmektedir.</li></ul><p>Avrupa Üroloji Birliği (EAU) tedavi kılavuzunda da erektil disfonksiyon tedavisinde ESWT’ nin ilk seçenek olarak düşünülebileceği bildirilmiştir.</p><p><strong>Ürolojide Şok Dalga Tedavisinin (ESWT) Fark Yaratan Özellikleri Nelerdir?</strong></p><p class="ql-align-justify">Peyronie hastalığının tedavisindeki amaç bu şok dalgaları yoluyla ağrının giderilmesi ve plak varlığında plak gelişimini azaltmak/durdurmak ve plağın yumuşamasını sağlamaktır. Özellikle akut dönemde oldukça etkili bir yöntemdir. Bu tedavi yönteminin çok tercih edilmesinin sebebi diğer tedavi seçeneklerine göre hiçbir yan etkisinin olmaması, tedavi süresince hastanın normal hayatına devam edebilmesi, seanslar esnasında hastanın herhangi bir ağrı hissetmemesi ve tedavi sonucunda kalıcı çözümler sağlanmasıdır. ESWT Şok Dalga Tedavisi her biri 15-20 dakika süren ve 2 gün arayla uygulanan seanslarla yapılmaktadır.</p><p><strong>Ürolojide Şok Dalga Tedavisinin (ESWT) Uygulama Alanları Nelerdir?</strong></p><p class="ql-align-justify">Ürolojide şok dalga tedavisi ESWT son 10 yıldır öncelikle erektil disfonksiyon olarak tanımlanan peniste sertleşme bozuklukları tedavisinde kullanılmaktadır. Son yıllarda giderek artan araştırmalar sonucunda ESWT yönteminin erkeklerde; ereksiyon problemleri yanında, kronik prostatit, penis eğriliği yapan Peyronie hastalığı gibi hastalıklarda; kadınlarda ise; vajinal kuruluk, orgazm sorunları, idrar kaçırma ve sık idrara çıkma gibi sorunlarda faydalı olduğuna dair yayınlar ortaya çıkmıştır.</p><p class="ql-align-justify"><strong>Kronik prostat iltihabında ESWT:&nbsp;</strong>Kronik prostatit tedavisinde şok dalga tedavisi ile başarılı sonuçlar alınmaktadır. Prostatit varlığında prostatın etkilenen bölgelerinde şok dalga tedavisi sayesinde sağlıklı dokuları korurken, inflame dokularda damarlanmayı artırarak bu alanlarda inflamasyonun vücut immün sistemi sayesinde yok edilmesi hedeflenmektedir. Perine bölgesinden (testislerle anüs arası) uygulanan şok dalga tedavisi ile ağrısız olarak tedavi uygulanmaktadır. Şok dalgalarının oluşturduğu mikrotravmalar sonucu prostat içinde büyüme faktörlerinin salınımı artar, kök hücreler aktive edilerek prostatit nedeniyle bozulmuş doku hasarı düzeltilir. Prostata düşük yoğunluklu şok dalga tedavisi (ESWT) haftada bir defa uygulanmakta, 20 dakika sürmekte ve toplam 6-12 seans halinde uygulanmaktadır. Anestezi gerektirmez ve hiçbir yan etkisi yoktur. Şok dalga tedavisi ve prostat ozon tedavisi birlikte yapılabilmektedir ve bu sayede çok daha fazla başarı elde edilmektedir. Prostatit şok dalga tedavisi, kronikleşen ve hastaya ciddi rahatsızlıklar veren iltihabın (inflamasyon) giderilmesinde etkin rol oynamaktadır.</p><p class="ql-align-justify"><strong>Peyronie hastalığında ESWT:&nbsp;</strong>Penis eğriliği olarak bilinen sorun doğuştan değil, sonradan gelişmiş ise tıp dilinde adı Peyronie hastalığıdır. Peyronie hastalığının, penis eğriliğinin henüz yerleşmediği akut dönemde teşhis edilmesi hastalığın tedavisi açısından oldukça önemlidir. Bu yüzden ereksiyon halindeyken peniste ağrı hisseden ya da penis üzerinde anormal sertlikler tespit eden erkeklerin kısa zamanda bir uzman hekime muayene olmaları oldukça önemlidir. Peniste ağrı ya da penis üzerinde sertlikler olduğunda detaylı tetkikler yapılmakta, hastalığın tam olarak teşhisi ve hangi aşamada olduğu belirlenmektedir. Fizik muayene bulguları, hasta öyküsüne ek olarak, laboratuvar ve radyolojik tetkikler tanı sürecinde yardımcı olmaktadır. Tanı ve evre belirlendikten sonra hastaya özgü tedavi planı oluşturulmaktadır. Günümüzde en yaygın olarak kullanılan tedavi yöntemi ED SWT Şok Dalga Tedavisidir. Bu tedavi özellikle erken dönemde ağrı ve ereksiyon problemleri için çok başarılıdır. Hastanın değerlendirilme sonucuna göre tedaviye ozonlu PRP ve/veya kök hücre tedavisi eklenmektedir. Peyronie tedavisinde kullanılan 3. jenerasyon cihaz olan ED SWT ile daha geniş alana, daha etkili güçlü, direk etki ile penisin istenen her bölgesine ulaşabilme özellikleriyle çok başarılı bir sonuç ortaya çıkarmaktadır.</p><p><strong>Ürolojide Şok Dalga Tedavisi&nbsp;(ESWT) hakkında sık sorulan sorular</strong></p><p><strong>Ürolojide Şok Dalga Tedavisinin (ESWT)&nbsp;Etki Mekanizması Nedir?</strong></p><p>ESWT uygulanan bölgede inflamasyona neden olup, kan akışını hızlandırarak, vücudun kendini onarma mekanizmalarını uyarır ve hastalıklarda iyileştirici etki oluşturur.</p><p class="ql-align-justify"><strong>Ürolojide Şok Dalga Tedavisinin (ESWT) Penis Üzerine Etkileri Nelerdir?</strong></p><p class="ql-align-justify">Şok dalga tedavisi ile peniste yeni kan damarlarının oluşması amaçlanır. ESWT ile penil kök hücreler harekete geçer ve kan akışı tekrar başlar. Nihayetinde de erkek cinsel organının yeniden sertleşmesi hedeflenir. Şok dalga tedavisi hafif, orta ve şiddetli sertleşme sorunu yaşayan tüm erkeklerde uygulanabilir. Ancak hafif ve orta derecede sertleşme sorunu olan hastalarda daha etkili sonuçlar elde edilir. Sertleşmenin fiziksel bir nedenle sekteye uğradığı durumlarda (şeker hastalığı, tansiyon yüksekliği, kan yağlarının yüksekliği gibi) doğru hastalara uygulandığında oldukça tatmin edici sonuçlara ulaşılır. Penis içerisindeki kök hücreler uyarıldığı ve kanlanma sağlandığı için kalıcı iyilik sağlanabilir. Bilindiği gibi sertleşmeyi sağlayan ilaç kullanımında böyle kalıcı bir durum söz konusu değildir. Kullanılan ilaçların sertleşmeye yardımcı olma derecesi de zamanla azalabilir. Diğer bir alternatif ise vakum pompası kullanımıdır. Cerrahi yöntemle penis içine yerleştirilen implant (mutluluk çubuğu) tedavisine de erektil disfonksiyon durumunda başvurulabilir. Tüm bu seçeneklerin önemli faydaları olmasına karşın kalıcı iyileşme sağlayabilmesi, daha zararsız ve hasta için daha kolay bir tedavi yöntemi olması nedeniyle ESWT’ yi ilk tedavi seçeneği olarak belirtmek mümkündür.</p><p><strong>&nbsp;</strong></p><p><strong>Ürolojide Şok Dalga Tedavisinin (ESWT) Yan Etkileri Var mı?</strong></p><p class="ql-align-justify">Ürolojide Şok Dalga Tedavisinin bilinen önemli bir yan etkisi yoktur. Tedavide şok dalgaları vücut dışından uygulanır. Penis damarları yeniden uyarılır. Tekrar harekete geçmesi amaçlanır. Girişimsel bir işlem yapılmaz. Bu sayede bir yan etkisi beklenmez. Uygulama sonrası penis üzerinde geçici kızarıklık ve şişlik oluşabilir.</p><p><strong>Kimler&nbsp;Ürolojide Şok Dalga Tedavisi (ESWT) İçin Uygun Aday Değildir?</strong></p><p class="ql-align-justify">Bir önceki soruda da belirttiğimiz gibi, sertleşme problemi psikolojik, hormonal veya sinir dokularından kaynaklı ise ESWT tedavisi hasta üzerinde kayda değer bir etki oluşturmayacaktır.</p><p class="ql-align-justify">Ek olarak sistemik enfeksiyonu olan hastalara, kalp pili kullanan ve eklem kemik ameliyatı olmuş kişilere ESWT uygulaması önerilmez.</p><p><strong>&nbsp;</strong></p><p><strong>Ürolojide Şok Dalga Tedavisinden (ESWT) Sonra Hastalar Nelere Dikkat Etmelidir?</strong></p><p class="ql-align-justify">ESWT cerrahi bir işlem olmadığı ve anestezi uygulanmadığı için hastalar işlem sonrası evlerine işlerine dönebilirler. İşlem sonrası dikkat edilmesi gereken belki de en önemli konu hastalarımızın beklentilerini yönetmektedir. ESWT ile tek seansta sonuç alınması güçtür. Kimi zaman ilk seanstan sonra sertleşme görülebilir. Ancak bu durum genellikle geçicidir. Nihai sonuç için bir ay beklemek gerekir.</p><p><strong>Ürolojide Şok Dalga Tedavisinin (ESWT)&nbsp;Başarısız Olma İhtimali Var Mı?</strong></p><p>Yapılan çalışmalar ESWT’ nin doğru hastalara uygulandığında erkek IIEF (erektil fonksiyon indeksi) skorunda yükseliş olduğunu göstermektedir.</p><p><strong>Ürolojide Şok Dalga Tedavisi (ESWT) Ne Kadar Sürer?</strong></p><p class="ql-align-justify">Tedavinin toplam süresi hastadan hastaya değişir. İkişer gün arayla üç seans uygulaması sonucu 1-2 haftada bitebileceği gibi, 18-24 seans da uygulanabilir. Ancak kayda değer kalıcı sonuçların ortaya çıkması için bir ay beklemek gerekir. Bir seans ise ortalama 20 dakika sürer.</p><p class="ql-align-justify">ESWT penise ya da vücudun diğer organlarına bir zarar vermez. ESWT cihazı böbrek taşlarında kullanılan sistemle benzerdir ancak ESWT’ de kullanılan şok dalga gücü daha düşük yoğunluktadır.</p><p>&nbsp;</p><p>&nbsp;</p><p><br></p><p><em> </em></p><p><em> </em></p><p>&nbsp;</p><p><a href="https://www.memorial.com.tr/doktorlar/a-egemen-avci?hastane=atasehir&amp;bolum=uroloji" rel="noopener noreferrer" target="_blank" style="color: windowtext;"><img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAMAAAAoyzS7AAAAAXNSR0ICQMB9xQAAAANQTFRFAAAAp3o92gAAAAF0Uk5TAEDm2GYAAAAJcEhZcwAAEnQAABJ0Ad5mH3gAAAAZdEVYdFNvZnR3YXJlAE1pY3Jvc29mdCBPZmZpY2V/7TVxAAAACklEQVQY02NgAAAAAgABmGNs1wAAAABJRU5ErkJggg=="></a></p><p>&nbsp;</p><p>&nbsp;</p><p>Formun Üstü</p><h3>&nbsp;</h3>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('azospermi', 'AZOSPERMİ', 'Erkek Kısırlığı', 'Microscope', '<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;AZOSPERMİ</strong></p><p class="ql-align-justify"><strong>Tanım</strong>;<strong> Azospermi</strong> ejakulatta spermatozoanın görülmemesi olarak tanımlanır. Genel olarak çiftlerin %15’inde fertilite problemi saptanmaktadır. Bu sebeple başvuran çiftlerin %30-40’ında neden olarak erkek faktörü rol oynar. Azospermi tüm erkeklerin yaklaşık %1’ inde görülürken, erkek kaynaklı infertilitenin yaklaşık %10–15’inden sorumlu olup erkek infertilitesinin en ciddi formudur.</p><p class="ql-align-justify">Obstrüktif azospermi testiküler ya da genital duktal sistemde tıkanıklık olmasıdır. Nonobstrüktif azospermi ise (NOA) normal ejakülat volümüne rağmen en az iki sperm analizinde sperm görülmemesidir. Bu da temelde spermatogenesisin bozulmasından kaynaklıdır. </p><p class="ql-align-justify">NOA histopatolojik olarak ise hipospermatogenezis, matürasyon arresti ve Sertoli-cell only (SCO) olarak gruplandırılabilir. Hipospermatogeneziste spermatogenezisin tüm evreleri tamamlanmış iken sayıda azalma mevcuttur. Matürasyon arresti spermatogenezisin tamamlanamadığını ve primer, sekonder spermatosit veya spermatid evresinde durduğunu işaret eder. Bu nedenle olgun spermatozoa bulunmaz. SCO sendromunda ise germinal epitelyum tamamen yoktur. Bunun yanı sıra NOA hastalarında mikst tip histopatolojilerde görülebilir. En az iki sperm testinde sperm görülmediği zaman mutlaka santrifüj ile doğrulanıp doğrulanmadığı kontrol edilmelidir. Çünkü semen analizine dayalı NOA tanısı alan hastaların %35’inde santifüj sonrası sperm bulunabilir ki bu da kriptozoospermi olarak adlandırılır. Azospermi tanısından sonra ise obstrüktif etiyolojiler ekarte edilmeli ve semen hacmi incelenmelidir.</p><p class="ql-align-justify">NOA tanısı konulduktan sonra ise hastaya detaylı değerlendirme yapmak hem infertilite hem de sistemik sebepler dolayısı ile elzemdir. Dikkatli anamnez altın kural olup yaş, vücut kitle endeksi, geçirilmiş enfeksiyonlar, kriptorşidizm öyküsü, infertilite süresi, ilaç kullanım öyküsü (steroid), kemoterapi ya da radyoterapi öyküsü sorgulanmalıdır. </p><p class="ql-align-justify"><strong>Fizik muayenede</strong> tiroid, kalp, akciğer ve batın muayenesi yapılmalı, jinekomasti gibi bulgular atlanmamalıdır. Testis muayenesinde normal testis volümüne göre (18–20 ml) küçülme veya atrofi izlenebilir. Bu da spermatogenezisin etkilendiğinin doğrudan göstergesidir. Hormonal değerlendirme primer ve sekonder ayrımını yapmayı kolaylaştırır ve hastanın tedavisinin doğru şekillenmesine yardımcı olur. Bu evrede folikül uyarıcı hormon (FSH), testosteron, inhibin B gibi parametreler hem endokrin patolojilerini anlamada hem de histopatolojik etiyolojiye yardımcı olur.</p><p class="ql-align-justify"><strong>Markerler ve genetik</strong>; Genetik değerlendirme bu hastalarda mutlaka yapılmalıdır. Karyotip ve azoospermi faktör (AZF) analizi en sık kullanılan genetik testlerdir. Azospermik erkeklerin %15’inde, oligospermik erkeklerin ise %5’inde genetik anormallikler görülmüş olup Klinefelter ve Kallman sendromu gibi olgular atlanmamalıdır. Klinefelter sendromu en yaygın görülen genetik anormallikler olmakla birlikte 47-XXY, ufak testis, az kıllanma ve jinekomasti ile karakterizedir. KAL1 ya da FGFR1 gen defektleri de anozminin eşlik ettiği hipogonadotropik hipogonadizm tablosu olan Kallman sendromunu işaret eder. AZF geni Y kromozomunun (Yq) uzun kolunda yerleşmiş olup üç alt tip barındırır ve AZFa, AZFb ve AZFc olarak adlandırılır. NOA vakalarının %3–10’unda AZF mutasyonu izlenmektedir. Bu alt tiplerdeki mikrodelesyonların belirlenmesi yapılacak cerrahi işlemin başarısını öngörmektedir. Yq mikrodelesyonları babadan oğula genetik miras olarak geçtiği için bu hastalara doğacak erkek çocuklarında aynı ya da benzer infertilite veya genetik anomalilerin görülebileceği bilgisi verilmelidir. </p><p class="ql-align-justify">TESE öncesinde sperm bulunabilmesini öngören birçok marker tanımlanmıştır. Karyotip analizi ve AZF için yapılan PCR analizleri en meşhur yöntemler olsa bile JMJD1A, RNF8, SPEM1 ve VASA gibi sperm ekstrasyon sonuçları pozitif olan birçok gen mevcuttur. Bunun yanında proteomik çalışmalar da sperm başarı oranını tahmin etmede kullanılmaya başlanan yöntemler arasındadır. Seminal plazmada saptanacak olan Clusterin, HE1 ve TEX101 gibi markerlar hem non invaziv olarak kolay elde edilebilir hem de sperm yakalama başarı şansı hakkında bilgi verirler. Yine de sperm ekstrasyon oranlarının yüksek veya düşük olduğunu tahmin etmek tek başına yeterli değildir. Dorosh ve ark. yaptığı çalışmada spermatogenezisin son evresinde ACR ve GAPDHS marker ekspresyonları saptanmış fakat bu markera sahip NOA’lı hastaların yüksek fertilizasyon oranlarına rağmen (%71-%66) klinik gebe kalma oranları (%6-%8) çok düşük görülmüştür. Whole-some sequencing yöntemi ile detaylı gen taraması çalışmaları yapılmakta ve hangi gen gruplarında hasar olduğu ve sperm ekstrasyon başarısına etkisi araştırılmaktadır. Kherraf ve ark. çalışmasına göre NOA’lı vakalarda DNA tamir veya piwi genlerinde, mayotik ve post-mayotik matürasyon genlerinde hasar saptanmıştır. Mayotik matürasyon genlerinde hasar bulunan hastalardan ise TESE yardımı ile sıfır ya da sıfıra yakın ihtimalle sperm elde edilebileceği ve gereksiz cerrahiden kaçınabileceği vurgulanmıştır. Spermatogonial stem cell (SCC) transplantasyonu (kök hücre ile genetik tedavi) sayesinde in vitro sertoli hücreleri tarafından spermatozoa aktivasyonuna olanak sağlanabilir. Potansiyel yan etki olarak kanser gelişimini tetiklemesi görülse de SCC sayesinde gelecekte infertilite problemine kökten çözüm sağlanabilir. Son yılların en merakla takip edilen yapay zekâ (AI) teknolojisi de yine infertilite alanında kullanılmaya başlanmıştır. Yapay zekâ çoklu ve farklı alandaki sayısız veriyi kombine ederek NOA’ lı hastalarda uygulanan sperm elde etme operasyonlarının başarı oranını tahmin edebilir.</p><p class="ql-align-justify"><strong>Tedavi</strong>; İnfertilite tedavisinde güncel olarak hormonal/medikal tedavi ve sperm elde etme kullanılmaktadır. Hormonal tedavi her hasta için uygun olmamakla birlikte özel seçilmiş hasta grubunda kullanılabilir fakat fayda vermesi açısından üroloji dünyasında bir birliktelik halen yoktur. Potansiyel olarak üç etiyolojinin bu tedaviden yarar görmesi daha olasıdır. Hipogonadotropik hipogonadizm (HH), fazla steroid ya da androjen alımı ve hipergonadotropik hipogonadizm olarak bu gruplar sınıflandırılabilir.</p><p class="ql-align-justify">Hormonal tedaviler her ne kadar altta yatan sebebi ortadan kaldırmasa da veya tamamen patolojiyi yok etmese de sonraki adımda yapılacak olan cerrahi işlemin başarı şansını artırdığı gösterilmiştir.</p><p class="ql-align-justify">NOA’nın günümüzde halen ana tedavisi mikro TESE (mikroskobik testiküler sperm ekstraksiyonu)dir. Başarılı sperm bulma ihtimalinin ayrıca testiküler histolojiye bağlı olduğu bilinmektedir. Hipospermatogenezis en yüksek başarı oranına sahipken (%73–100), geç matürasyon arresti (%27–86) ile erken matürasyon arresti (%27–40) onu takip etmekte, en düşük oran ise %22–41 ile Sertoli cell only dedir. Tek başına tanısal biyopsi bu hastalarda önerilmemektedir fakat sperm elde etme sırasında bu işlem uygulanabilir.</p><p class="ql-align-justify">Varikosel varlığı ve cerrahi olarak düzeltilmesi ile ilgili önerilen ve önerilmeyen çok sayıda yayın bulunmaktadır. Ancak tespit edilmiş bir varikosel varsa biz bu sebebin ortadan kaldırılmasını öneriyoruz.</p><p class="ql-align-justify"><strong>Sonuç olarak</strong>, NOA’ nın kesin tedavisi halen net olarak bulunamamış olsa da hormonal tedavi ve öngörülebilirliği arttıran markerler yardımıyla sperm elde etme yöntemleri ile NOA tanılı hastaların biyolojik baba olma şansı bulunmaktadır. </p><p class="ql-align-justify">Önümüzdeki dönemlerde özellikle genetik anlamda kök hücrelerden sperm üretimi ile bu problem tamamen çözülebilecektir.</p><p class="ql-align-justify">&nbsp;</p><p><br></p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('vari-kosel', 'VARİKOSEL', 'Erkek Kısırlığı', 'Microscope', '<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                                               VARİKOSEL</strong></p><p class="ql-align-justify"><strong>TANIM</strong>; Testis (yumurtalık) in kirli dediğimiz venöz kanını taşıyan damarlarında meydana gelen genişlemeye varikosel denir. %90 oranında anatomik durumlardan dolayı sol tarafta görülür. %10 civarında sağda da görülebilir. Kısaca yumurtalık damarlarındaki varis olarak tanımlanabilir. Tüm erkeklerde %10-15 görülebilirken kısırlık sebebiyle başvuran hastaların yaklaşık %40’ın da varikosel görülmektedir.</p><p class="ql-align-justify"><strong>NEYE SEBEP OLUR?</strong> Varikosel tedavi edilmediği takdirde yumurtalıklarda biriken kirli kana bağlı olarak zamanla yumurtalığın zarar görmesi, küçülmesi ve sperm parametrelerinde bozulmalara sebep olarak kısırlığa sebebiyet verebilir. </p><p class="ql-align-justify"><strong>BELİRTİLERİ</strong>; </p><p class="ql-align-justify">Kısırlık, varikosel düzeltilebilir erkek kısırlığının en sık sebebidir,</p><p class="ql-align-justify">Yumurtalık damarlarında şişlik,</p><p class="ql-align-justify">Yumurtalık kıvamında yumuşama ve küçülme,</p><p class="ql-align-justify">Yumurtalık ve kasıkta ağrı..</p><p class="ql-align-justify"><strong>VARİKOSEL TANISI;</strong></p><p class="ql-align-justify"><strong>Varikoselin tanısı</strong>&nbsp;esas olarak deneyimli bir ürolog tarafından fizik muayene ile konulur. Tanıyı desteklemek ve de testis boyutu gibi parametreleri de daha kesin görmek amaçlı Skrotal Doppler Ultrasonografi yapılabilir ancak tanı için mutlak gerekli değildir.</p><p class="ql-align-justify">Ayrıca tedavi gereksinimini de değerlendirmek için uygun koşullarda Semen Analizi yapılması gereklidir.</p><p class="ql-align-justify"><strong>VARİKOSEL NEDEN TEDAVİ EDİLMELİ?</strong></p><p class="ql-align-justify"><strong>Varikosel</strong>&nbsp;ilerleyici testis hasarına ve sonuçta fertilitenin azalmasına neden olur. Varikoselin ayrıca DNA hasarına neden olarak yine fertilitenin azalmasına neden olduğu gösterilmiştir. Bu olumsuz etki uygun cerrahi tedavi ile azaltılabilir.</p><p class="ql-align-justify"><strong>VARİKOSEL AMELİYATI</strong></p><p class="ql-align-justify">Varikosel tanısı konulduktan sonra hastanın testis boyutları, semen parametreleri, kısırlık problemi olup olmadığı değerlendirilir; bunlarda problem yok ise destek tedavisi ile hasta takip edilebilir.</p><p class="ql-align-justify"><strong>Varikoselin cerrahi tedavisi</strong>&nbsp;testis boyutlarında anlamlı azalma, sperm parametrelerinde düşüş olması gibi durumlarda önerilmektedir.</p><p class="ql-align-justify">Varikosel cerrahisi birçok teknikle yapılabilir. Bu yöntemlerden Mikrocerrahi Varikoselektomi daha yüksek başarı oranları, daha düşük komplikasyon ve nüks olasılığı ile ön plana çıkmıştır.</p><p class="ql-align-justify">Bu yöntem ile kasık bölgesine 2 cm’lik küçük bir kesi yapılarak mikroskopik büyütme altında daha hassas ve başarılı cerrahi yapılmaktadır.</p><p class="ql-align-justify">Tek taraflı ya da çift taraflı olmasına göre operasyon süresi ortalama 45 dk’dir. Hastalar aynı gün taburcu edilebilmekte ve de 2-3 gün sonra normal günlük aktivitelere dönebilmektedir.</p><p class="ql-align-justify"><strong>Varikoselektomi sonrası</strong>&nbsp;sperm parametreleri 6. Ayda değerlendirilir. Ameliyat sonrası spontan gebelik şansı ciddi oranda artmaktadır. Ayrıca gebeliğin kendiliğinden olmadığı durumlar için bile sperm parametrelerinde düzelme sayesinde yardımcı üreme teknikleri ile gebelik oranı da artmaktadır.</p><p class="ql-align-justify">&nbsp;</p><p class="ql-align-justify">&nbsp;</p><p class="ql-align-justify">&nbsp;</p><p class="ql-align-justify">&nbsp;</p><p class="ql-align-justify">&nbsp;</p><p><br></p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('bph-iyi-huylu-prostat', 'BPH (İyi Huylu Prostat)', 'İlaç ve girişimsel seçenekler', 'Shield', '<h3>BPH Nedir?</h3><p>Prostat bezinin yaşla birlikte büyümesi durumudur.</p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('tas-cerrahisi', 'Taş Cerrahisi', 'Böbrek ve üreter taşı endoürolojisi', 'TestTube', '<h3>Taş Cerrahisi Nedir?</h3><p>Böbrek, üreter ve mesane taşlarının minimal invaziv tedavisi.</p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('kronik-prostatit', 'Kronik Prostatit', 'Neden odaklı tanı ve tedavi', 'Microscope', '<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PROSTATİT</strong></p><p class="ql-align-justify">Prostatit tüm erkeklerde bulunan prostat bezinin kısaca iltihaplanması durumu olarak tanımlanabilir. Dört grupta incelenebilir. Akut bakteriyel prostatit, kronik bakteriyel prostatit, kronik prostatit/kronik pelvik ağrı sendromu ve asemptomatik inflamatuar prostatit olarak sınıflandırılabilir. Bu sınıflama içerisinde en sıkıntılı grup üçüncü maddedeki <strong>kronik prostatit/kronik pelvik ağrı sendromu</strong>dur. Bu da&nbsp;herhangi bir enfeksiyöz etkenin veya başka bir faktörün bulunamadığı &nbsp;primer tip ve başka bir nedene bağlı oluşan sekonder tip olarak iki grupta değerlendirilebilir.</p><p class="ql-align-justify"><br></p><p class="ql-align-justify">Kronik primer pelvik ağrı sendromu (KPPAS), erkek ve kadınlarda ağrıyı açıklayabilecek kanıtlanmış bir enfeksiyon veya diğer belirgin lokal patolojinin olmadığı durumlarda kronik pelvik ağrının ortaya çıkmasıdır. Genellikle olumsuz bilişsel, davranışsal, cinsel veya duygusal sonuçların yanı sıra; alt üriner sistem, cinsel, bağırsak veya jinekolojik işlev bozukluğunu düşündüren semptomlarla ilişkilidir. Kronik Primer Pelvik Ağrı Sendromu, kronik pelvik ağrının bir alt bölümüdür.</p><p class="ql-align-justify">Genital yapıların tümüyle ilişkili olabilir ancak sıklıkla erkeklerde prostat bezinde, kadınlarda da mesane de ortaya çıkar. Bu nedenle erkeklerde kronik prostatit, kadınlarda da <strong>ağrılı mesane sendromu</strong> veya daha sıklıkla <strong>interstisyel sistit</strong> olarak adlandırmalar yapılmaktadır.</p><p class="ql-align-justify">Öykü ve Fizik Muayene;</p><p class="ql-align-justify">Kronik pelvik ağrısı olan hastaların değerlendirilmesinde öykü çok önemlidir. Ağrı sendromları; başka bir patoloji yokluğunda, <em>son altı ayın en az üç ayında mevcut olan pelvis bölgesinde hissedilen ağrının öyküsünden</em> yola çıkarak konulan semptomatik tanılardır. Bu, bakteriyel enfeksiyon, kanser, pelvik organların primer anatomik veya fonksiyonel hastalığı ve nörojenik hastalıkların dışlanmasını gerektirir. Klinik muayene genellikle iyi bir öyküden elde edilen ilk izlenimleri doğrulamaya veya dışlamaya yardım eder. Lokal muayenenin yanı sıra, genel kas-iskelet sistemi ve nörolojik muayenenin de değerlendirme sürecinin ayrılmaz bir parçası olarak düşünülmesi ve uygun olduğunda yapılması gerekmektedir.</p><p class="ql-align-justify">Belirtileri;</p><ul><li class="ql-align-justify">İdrar öncesi sırasında veya sonrasında yanma</li><li class="ql-align-justify">İdrar yapmaya başlamada zorluk</li><li class="ql-align-justify">İdrar akışı başladıktan sonra devam ettirmede zorlanma</li><li class="ql-align-justify">Sık sık (günde 7-8’ den fazla ve gece uyuduktan sonra en az 4-5 kez) veya acil idrara çıkma ihtiyacı</li><li class="ql-align-justify">İdrar kesesinin tam boşaltılamaması hissi</li><li class="ql-align-justify">Penisin üstünde, kasık bölgesinde skrotumun içinde veya altında veya sırtta veya makat bölgesinde hissedilen ağrı</li><li class="ql-align-justify">Orgazm sırasında veya sonrasında yaşanan ağrı</li><li class="ql-align-justify">Kas ağrıları</li></ul><p class="ql-align-justify">Tedavi;</p><p class="ql-align-justify">Genital hijyen, düzenli eksersizler, sıvı alımının ayarlanması gibi yaşam alışkanlıkları düzenlenmelidir,</p><p class="ql-align-justify">Ağrı yönetimi en önemli aşamayı oluşturur,</p><p class="ql-align-justify">En az altı hafta sürecek antibiyoterapi çoğu hastada halen başarı ile uygulanmaktadır,</p><p class="ql-align-justify">İdrar şikayetleri için alfa blokerler,</p><p class="ql-align-justify">PTNS (perkütan tibial sinir stimülasyonu) veya TTNS (transkütanöz tibial sinir stimülasyonu) genel anlamda Aşırı Aktif Mesane, Urge İnkontinans, İnterstisyel sistit (ağrılı mesane) ve Kronik Prostatit te kullanılabilir.</p><p class="ql-align-justify">Son yıllarda gittikçe popüler olan ESWT tedavileri de başarı ile uygulanmaktadır.</p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('prp-eksozom-kok-hucre', 'PRP / Eksozom / Kök Hücre', 'Rejeneratif uygulamalar', 'Syringe', '<h3>Rejeneratif Tıp Uygulamaları Nedir?</h3><p>Vücudun kendi iyileşme mekanizmalarını kullanan tedavi yöntemleri.</p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('i-drar-kacirma', 'İDRAR KAÇIRMA', 'Üriner İnkontinans', 'Waves', '<p><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                       &nbsp;İNKONTİNANS (İDRAR KAÇIRMA)</strong></p><p><strong>TANIM</strong>: Kısaca istem dışı idrar kaçırma olarak tanımlanabilir.</p><p><strong>TÜRLERİ</strong>: <strong>Stres idrar kaçırma: </strong>Öksürme, gülme, hapşırma, ağır kaldırma gibi karın içi basıncının arttığı durumlarda olan idrar kaçırma tipidir. Mesane boynu, sfinkter yapısı (idrar tutma kası) ve üretra (idrar kanalı) etrafını saran pelvik taban kaslarındaki yetersizlik nedeniyle gelişir. Daha çok anatomik faktörler etkilidir. Tedavisinde de bu kasların güçlendirilmesi, ilaçla medikal tedavi ve çoğunlukla cerrahi operasyonlar gerekir.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Urge (sıkışma) tipi idrar kaçırma: </strong>Aniden ortaya çıkan ve tuvalete yetişemeden oluşan idrar kaçırma tipidir. Aşırı aktif mesane hastalığının belirtisi olabilir.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Over Flow (dolma taşma) tipi idrar kaçırma:</strong> Mesanenin yeterince boşaltılamadığı ve kapasitesinin dolarak taştığı idrar kaçırma tipidir. Prostat büyümesi gibi tıkanıklığa bağlı hadiselere sekonder gelişebileceği gibi MS, diyabet gibi idrar torbasında duyusal hasar oluşturan sebeplere de bağlı oluşabilir.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Mixt (karışık) tip idrar kaçırma: </strong>Hem stres hem de sıkışma tipi idrar kaçırmanın birlikte olduğu tip olarak adlandırılabilir.</p><p><strong>NEDENLERİ</strong> arasında,</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Aşırı kilo, </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Diyabet hastalığı, </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Pelvik kas ve yapıların zayıflığı, </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Gebelikler ve doğumlar, </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Nörolojik hastalıklar (multiple skleroz, parkinson vb), </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Menopoz, </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Prostat kanseri gibi geçirilen pelvik ve retroperitoneal cerrahiler, </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Radyoterapiler, </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;AŞIRI AKTİF MESANE, </p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;İdrar yolu enfeksiyonları sayılabilir.</p><p><strong>TANI: </strong>En önemli kısım h<span style="color: rgb(27, 27, 27);">astanın öyküsü ve fizik muayenesinin yapılmasıdır. Daha sonra idrar tetkiki, idrar kültürü, sebebin tespiti ve tedavinin düzenlenmesi açısından üroflowmetri, ürodinami, ultrasonografi ve sistoskopik incelemelerin bir ya da birkaçı yapılabilir.</span></p><p><strong style="color: rgb(27, 27, 27);">TEDAVİ:</strong><span style="color: rgb(27, 27, 27);"> Öncelikli olarak yaşam tarzı değişiklikleri olarak adlandırabileceğimiz; diyet ile normal vücut ağırlığına gelebilmek, diyabetik hastalar için kan şekeri regülasyonu, çay, kahve, acı, baharat ve gazlı içeceklerden mümkün olduğunca uzak durmak, pelvik taban kaslarının güçlendirilmesi için kegel eksersizleri vs ile pelvik taban rehabilitasyonu, düzenli spor yapılması ve gün içinde aldığımız sıvının miktar ve zaman aralıklarının düzenlenmesi gerekmektedir. </span></p><p><span style="color: rgb(27, 27, 27);">Daha sonra nedene yönelik tedaviler planlanmalıdır. Örneğin basit bir sistit atağında uygun bir antibiyotik ile tedavi sistemi rahatlatacaktır.</span></p><p><strong style="color: rgb(27, 27, 27);">Kadınlarda İdrar Kaçırma Ameliyatı </strong></p><p><strong style="color: rgb(27, 27, 27);">Stres inkontinansta düşünülebilir:</strong><span style="color: rgb(27, 27, 27);">&nbsp;Günümüzde bu tip idrar kaçırma için en sık kullanılan cerrahi yöntem trans obturatuar tape (TOT) ya da trans vajinal tape (TVT) operasyonlarıdır. Gayet etkin olan bu yöntem için hasta seçimi çok önemlidir. Ayrıca bu askı ameliyatlarında kullanılan suni mesh (yama, askı materyali) konusunda hastalar bilgilendirilmelidir.</span></p><p><strong style="color: rgb(27, 27, 27);">Erkeklerde İdrar Kaçırma Ameliyatı </strong></p><p><span style="color: rgb(27, 27, 27);">Erkeklerde görülen stres tipi idrar kaçırma ise genellikle prostat ve mesane kanseri cerrahisi sonrası oluşur. Bu durumda yapay idrar tutma büzücüsü (artifisyel üriner sfinkter) yerleştirilerek tedavi sağlanabilir.</span></p><p><strong style="color: rgb(27, 27, 27);">Aşırı aktif mesane (AAM):</strong><span style="color: rgb(27, 27, 27);">&nbsp;</span></p><p><span style="color: rgb(27, 27, 27);">İdrar depolama semptomlarıdır. Depolama semptomları şunlardır:</span></p><ul><li>Ani idrar yapma ihtiyacı ve bunun erteleyememe sıkıntısı</li><li>İstemsiz idrar kaçırma</li><li>Normalden daha sık idrar yapma ihtiyacı (Gündüz 8’ den az, gece 1 kere olmalı)</li><li>Gece idrar yapma ihtiyacı ile uyanma</li></ul><p><span style="color: rgb(27, 27, 27);">Aşırı aktif mesane için ideal tedavi henüz tam olarak bulunamamıştır. İlaç tedavileri başarıyla yapılabilmektedir. İlaçların semptomları iyileştirmede başarısız olduğu durumlarda, seçenekler arasında botulinum toksin-A (botoks uygulaması basit ve lokal anestezi ile bile uygulanabilirliği nedeniyle sık tercih edilmektedir. </span></p><p><span style="color: rgb(27, 27, 27);">Sakral sinir stimülasyonu,</span></p><p><span style="color: rgb(27, 27, 27);">Posterior tibial sinir stimülasyonu (PTNS) veya transkütanöz tibial sinir stimülasyonu (TTNS) gibi tedaviler özellikle ileri yaş ve medikal tedavi başarısızlık ve komplikasyon durumlarında başarılı tedaviler arasında yer almaktadır. </span></p><p><span style="color: rgb(27, 27, 27);">PTNS ve TTNS genel anlamda AAM, Urge İnkontinans, İnterstisyel sistit (ağrılı mesane), kronik prostatit te de kullanılabilir. Mixt tipte de kullanılabilir ancak stres inkontinansta çok etkili değildir. </span></p><p><span style="color: rgb(27, 27, 27);">&nbsp;</span></p><p><span style="color: rgb(27, 27, 27);">Tıbbi editör: Op. Dr. Bülent Sabri Keser</span></p><p><span style="color: rgb(27, 27, 27);">Güncelleme: 03.12. 2025</span></p><p><span style="color: rgb(27, 27, 27);">&nbsp;</span></p><p><span style="color: rgb(27, 27, 27);">&nbsp;</span></p><p><span style="color: rgb(27, 27, 27);">&nbsp;</span></p><p>&nbsp;</p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z'),
  ('asiri-akti-f-mesane', 'AŞIRI AKTİF MESANE', 'Sık İdrar', 'Waves', '<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                                 <strong>AŞIRI AKTİF MESANE (AAM)</strong></p><p class="ql-align-justify">Mesane kas yapısından meydana gelen, böbreklerde oluşan idrarı depolayan bir organımızdır. Mesaneyi boşaltabilmemiz için beyinden gelen uyarılarla detrusör dediğimiz kasların kasılması ve mesane çıkışında bulunan sfinkter dediğimiz subap mekanizmasının gevşemesi gerekmektedir. İdrar yapma sıklığı&nbsp;birçok faktöre bağlıdır. Özelliklede; alınan sıvı miktarı ile ilgilidir. Birçok insan tüm gün boyunca, günde 8 kereden az, gecede ya 1 kez idrara çıkar ya da hiç idrar yapma ihtiyacı duymaz.</p><p class="ql-align-justify"><strong>AAM SEMPTOMLARI:</strong></p><p class="ql-align-justify"><span style="color: black;">&nbsp;İdrar depolama semptomlarıdır. Depolama semptomları şunlardır:</span></p><ul><li class="ql-align-justify">Ani idrar yapma ihtiyacı ve bunun erteleyememe sıkıntısı</li><li class="ql-align-justify">İstemsiz idrar kaçırma</li><li class="ql-align-justify">Normalden daha sık idrar yapma ihtiyacı</li><li class="ql-align-justify">Gece idrar yapma ihtiyacı ile uyanma</li></ul><p class="ql-align-justify"><strong>AAM SEMPTOMLARININ NEDENLERİ:</strong> </p><p class="ql-align-justify">Bu gruptaki kişilerde, mesanelerinde ani ve spontan kasılmalar oluşur. Bazı insanlar&nbsp;mesane&nbsp;dolumunu daha hassas hissederler. Bazı kişilerde&nbsp;böbrekler&nbsp;gece daha fazla idrar üretir. Bu noktüriye neden olur. Bu durum ileri yaş ve belli tıbbi durumlarla ilgili olabilir. Bazı kişilerin daha küçük mesaneleri vardır ve daha çabuk dolar. Dolayısıyla daha sık idrar yapma isteği oluşur.</p><p class="ql-align-justify"><strong>TANI:</strong> AAM’ de en önemli tanı hikaye (kullandığı ilaçlar, mesane günlüğü vs) ve fizik muayene ile konur. Çoğu zaman idrar tetkiklerinde belirgin bir enfeksiyon ve kanamaya rastlanmaz. Ancak ayırıcı tanı açısından, idrar tetkiki, idrar kültürü, ultrason, üroflovmetri/ürodinami, sistoskopi gibi daha ileri tetkikler duruma göre yapılabilir.</p><p class="ql-align-justify"><strong>AAM HASTA UYUMU</strong></p><p class="ql-align-justify">Aşırı aktif&nbsp;mesane&nbsp;semptomları oldukça sıkıntı vericidir; fakat hayatınızı tehdit etmez. AAM semptomları uzun sure devam edebilir ve basit bir tedavisi yoktur. Birçok vakada hasta uyumu tedavinin ilk basamağıdır, sıklıkla farklı tedavi opsiyonları denenerek sizin durumunuza en uygun tedavi anlaşılabilir.</p><p class="ql-align-justify"> </p><p class="ql-align-justify"> Semptomlarınızla aktif olarak başa çıkabilirsiniz. Aşağıdaki maddeler hasta uyumunu sağlamada yardımcı olacaktır:</p><ul><li class="ql-align-justify">Doktorunuzla konuşarak hangi sıvıdan ne kadar ve ne zaman alacağınızı belirleyebilirsiniz.</li><li class="ql-align-justify">İdrar kaçırma&nbsp;probleminiz varsa doktorunuz size elbiselerinizin ıslanmaması için pet kullanmanızı önerebilir.</li><li class="ql-align-justify">Eğer doktorunuz önerirse, ani idrar hissettiğinizde idrarınızı daha uzun süre tutmaya çalışın. Bu mesanenizin eğitilmesine yardımcı olur ve kademeli olarak tuvalete gitme aralığınızı artırır.</li><li class="ql-align-justify">Pelvik kaslar yaşlanma ile zayıflar. Pelvik kasları sıkarak yapılan Kegel egzersizleri ani idrar hissinizi baskılamanıza yardımcı olur ve kaslarınızın gücünü tekrar kazanmasına yardımcı olur.</li></ul><p class="ql-align-justify"><strong>Hayat tarzı önerileri</strong></p><p class="ql-align-justify">Semptomlarınızı yönetmenize ve hayat kalitenizi arttırmanıza yardımcı olur.</p><ul><li class="ql-align-justify">Her gün en az (yaşanılan iklime göre değişmekle birlikte) 1,5-2,5 litre sıvı alın eğer daha çok alabilecekseniz doktorunuzla konuşun,</li><li class="ql-align-justify">Uzun seyahatler sırasında ve öncesinde daha az sıvı alın</li><li class="ql-align-justify">Gece idrar isteği ile uyanmamak için akşam daha az sıvı alın</li><li class="ql-align-justify">Alkol, çay ve kahve alımı özellikle gece bırakılmalıdır; çünkü bunlar idrar miktarını arttırır ve mesaneyi uyarır</li><li class="ql-align-justify">Bazı gıdalar mesaneyi uyararak AAM semptomlarını arttırır. Tüketilen gıdalardan; suni tatlandırıcılar, baharatlı&nbsp;gıdalar, kafein, turunçgiller ve bunların meyve suları ve gazlı içecekler kısıtlanmalıdır</li><li class="ql-align-justify">Kilo kontrolü (vücut kitle indeksi 18-25 kg/m2) kilo azaltılması idrar kaçırma semptomlarını iyileştirir</li></ul><p class="ql-align-justify"><strong>AAM ilaç tedavisi</strong></p><p class="ql-align-justify">Hastaların 1/3’ünde hasta uyumu ile alınan önlemler yetersiz kalır Önlemler yetersiz kaldığında doktorunuz size ilaç tedavisi önerebilir. Doktorunuzla birlikte hangisinin en iyi olduğuna karar verebilirsiniz.</p><p class="ql-align-justify"><strong>AAM de ikinci düzey tedavi</strong></p><p class="ql-align-justify">Bazen reçete edilen ilaçlar semptomlarınızı gidermez. Bu vakalarda diğer tedavi opsiyonları kullanılır.</p><p class="ql-align-justify"><strong>Sık kullanılan tedavi opsiyonları:</strong></p><p><span style="color: rgb(27, 27, 27);">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;İlaçların semptomları iyileştirmede başarısız olduğu durumlarda, seçenekler arasında botulinum toksin-A (botoks uygulaması basit ve lokal anestezi ile bile uygulanabilirliği nedeniyle sık tercih edilmektedir. </span></p><p><span style="color: rgb(27, 27, 27);">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Sakral sinir stimülasyonu,</span></p><p><span style="color: rgb(27, 27, 27);">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Posterior tibial sinir stimülasyonu (PTNS) veya transkütanöz tibial sinir stimülasyonu (TTNS) gibi tedaviler özellikle ileri yaş ve medikal tedavi başarısızlık ve komplikasyon durumlarında başarılı tedaviler arasında yer almaktadır. </span></p><p class="ql-align-justify">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style="color: rgb(27, 27, 27);">PTNS ve TTNS genel anlamda AAM, Urge İnkontinans, İnterstisyel sistit (ağrılı mesane), kronik prostatit te de kullanılabilir. Mixt tipte de kullanılabilir ancak stres inkontinansta çok etkili değildir. </span></p><p class="ql-align-justify">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Cerrahi yöntemler ile&nbsp;mesane&nbsp;kapasitesinin arttırılması.</p><p><span style="color: rgb(27, 27, 27);">&nbsp;</span></p><p><span style="color: rgb(27, 27, 27);">Tıbbi editör: Op. Dr. Bülent Sabri Keser</span></p><p><span style="color: rgb(27, 27, 27);">Güncelleme: 03.12. 2025</span></p><p class="ql-align-justify">&nbsp;</p><p class="ql-align-justify">&nbsp;</p><p class="ql-align-justify">&nbsp;</p><p>&nbsp;</p>', '2026-06-07T11:30:43.530Z', '2026-06-07T11:30:43.530Z');

create index idx_blog_posts_created_at on public.blog_posts (created_at desc);
create index idx_specialties_slug on public.specialties (slug);
create index idx_videos_display_order on public.videos (display_order);

commit;

select 'blog_posts' as table_name, count(*) from public.blog_posts
union all select 'specialties', count(*) from public.specialties
union all select 'videos', count(*) from public.videos;
